func GetCredentials() (*Credentials, error) {
	ak := os.Getenv("AWS_ACCESS_KEY_ID")
	sk := os.Getenv("AWS_SECRET_ACCESS_TOKEN")
	if ak == "" {
		ak = os.Getenv("AWS_ACCESS_KEY_ID")
