	credentialScope := dateStamp + "/" + region + "/" + service + "/aws4_request"
	hashedCanonical := sha256.Sum256([]byte(canonicalRequest))
	stringToSign := "AWS4-HMAC-SHA256\n" + amzDate + "\n" + credentialScope + "\n" + hex.EncodeToString(hashedCanonical[:])
