	signature := hex.EncodeToString(hmacSHA256(kSigning, stringToSign))
	auth := fmt.Sprintf("AWS4-HMAC-SHA256 Credential=%s/%s, SignedHeaders=%s, Signature=%s", creds.AccessKey, credentialScope, signedHeadersStr.String(), signature)
	req.Header.Set("Authorization", auth)
}

func hmacSHA256(key []byte, data string) []byte {
	h := hmac.New(sha256.New, key)
	h.Write([]byte(data))
	return h.Sum(nil)
}

// JSONRequest performs a JSON-protocol AWS request (SSM, SecretsManager) with retries
func JSONRequest(service, target string, payload interface{}, region string, creds *Credentials, retries int) (map[string]interface{}, int, error) {
	endpoint := GetEndpoint(service, region)
