				// if empty, return empty
				out = map[string]interface{}{}
			}
		}
		return out, resp.StatusCode, nil
	}
	if lastErr != nil {
		return nil, statusCode, lastErr
	}
	return nil, statusCode, fmt.Errorf("exceeded maximum number of attempts, %d", retries)
