	params, _ := resp["Parameters"].([]interface{})
	var out []SecretVersion
	for _, p := range params {
		m, _ := p.(map[string]interface{})
		val, _ := m["Value"].(string)
		desc, _ := m["Description"].(string)
		ver := ParseVersion(desc)
		// fallback to SDK Version if desc not numeric? Actually earlier history with desc "1" gave Version 1, SDK also 1. For desc non-numeric, Version 0.
