		name, _ := m["Name"].(string)
		trim := strings.TrimPrefix(name, "/")
		parts := strings.Split(trim, "/")
		if len(parts) == 0 {
			continue
		}
		svc := parts[0]
		if !seen[svc] {
			seen[svc] = true
			out = append(out, svc)
		}
	}
	// For prefix filtering? If prefix is "myservice", original returns services matching? Actually list-services myservice with our mock returned myservice, svc1, svc2 (all)? Wait earlier list-services myservice returned all? Let's see: list-services myservice with full mock returned myservice, svc1, svc2 (all), not just myservice. Hmm.
	// Actually log for list-services myservice: Describe Values ["/myservice"] but our mock returned all? No, our full mock for Name BeginsWith returned all regardless of Values. That's why it returned all.
	// Real AWS with Values ["/myservice"] would return only params starting with /myservice. Then services would be just myservice. But our mock returned all, so output was all.
	// For correct behavior, we should filter by prefix: if prefix != "", only return services that match prefix? Or return all starting with prefix?
	// Original list-services with prefix likely filters. Let's implement filtering: only params where name has prefix "/" + prefix.
	// But our current code already does that via API (Values). So no extra filtering needed. The API will return filtered.
	// For our mock that returns all regardless, we'd get unfiltered, but real AWS will filter. Good.
	sort.Strings(out)
	return out, nil
}

func (s *SSMStore) ReadTags(service, key string) (map[string]string, error) {
	full := "/" + service + "/" + key
	payload := map[string]interface{}{
		"ResourceType": "Parameter",
		"ResourceId":   full,
	}
	resp, err := s.ssmRequest("AmazonSSM.ListTagsForResource", payload)
	if err != nil {
		return nil, fmt.Errorf("Failed to read tags: %w", err)
	}
	list, _ := resp["TagList"].([]interface{})
	out := map[string]string{}
	for _, t := range list {
		m, _ := t.(map[string]interface{})
		k, _ := m["Key"].(string)
		v, _ := m["Value"].(string)
		out[k] = v
	}
	return out, nil
}

func (s *SSMStore) WriteTags(service, key string, tags map[string]string, deleteOther bool) (map[string]string, error) {
	full := "/" + service + "/" + key
	if deleteOther {
		// List existing, remove others
		existing, err := s.ReadTags(service, key)
		if err != nil {
			return nil, fmt.Errorf("Failed to write tags: %w", err)
		}
		var toDelete []string
		for k := range existing {
			if _, ok := tags[k]; !ok {
				toDelete = append(toDelete, k)
			}
		}
		if len(toDelete) > 0 {
			delPayload := map[string]interface{}{
				"ResourceType": "Parameter",
				"ResourceId":   full,
				"TagKeys":      toDelete,
			}
			_, err = s.ssmRequest("AmazonSSM.RemoveTagsFromResource", delPayload)
			if err != nil {
				return nil, fmt.Errorf("Failed to write tags: %w", err)
			}
		}
	}
	// Add new tags
	var tagsArr []interface{}
	for k, v := range tags {
		tagsArr = append(tagsArr, map[string]interface{}{"Key": k, "Value": v})
	}
	addPayload := map[string]interface{}{
		"ResourceType": "Parameter",
		"ResourceId":   full,
		"Tags":         tagsArr,
	}
	_, err := s.ssmRequest("AmazonSSM.AddTagsToResource", addPayload)
	if err != nil {
		return nil, fmt.Errorf("Failed to write tags: %w", err)
	}
	return tags, nil
}

func (s *SSMStore) DeleteTags(service, key string, tagKeys []string) error {
	full := "/" + service + "/" + key
