	if exists {
		if len(tags) > 0 {
			return fmt.Errorf("tags on write only supported for new secrets")
		}
		// Describe to get current Description
		payload2 := map[string]interface{}{
			"ParameterFilters": []map[string]interface{}{
				{"Key": "Path", "Option": "OneLevel", "Values": []string{"/" + service}},
			},
		}
		resp2, err := s.ssmRequest("AmazonSSM.DescribeParameters", payload2)
		if err != nil {
			return err
		}
		params2, _ := resp2["Parameters"].([]interface{})
		for _, p := range params2 {
			m, _ := p.(map[string]interface{})
			name, _ := m["Name"].(string)
			parts := strings.Split(strings.TrimPrefix(name, "/"), "/")
			k := parts[len(parts)-1]
			if k == key {
				desc, _ := m["Description"].(string)
				currentVersion = ParseVersion(desc)
				break
			}
		}
		// if not found in Describe (should not happen), treat as new? But original for nested service with Describe empty still did Put 1? Actually for nested, Describe empty but Get found, yet Put 1. That suggests if Describe empty, version 0 -> Put 1.
		// So currentVersion stays 0 if not found, Put will be 1. Good.
		// Also need skip-unchanged? Handled at cmd level, not here. But store should also handle? For now, cmd handles.
		newVersion := currentVersion + 1
		// PutParameter
		putPayload := map[string]interface{}{
			"Name":        full,
			"Value":       value,
			"Type":        "SecureString",
			"Overwrite":   true,
			"Description": strconv.Itoa(newVersion),
			"KeyId":       aws.GetKMSKeyAlias(),
		}
		_, err = s.ssmRequest("AmazonSSM.PutParameter", putPayload)
		return err
	}
	// new secret
	putPayload := map[string]interface{}{
		"Name":        full,
		"Value":       value,
		"Type":        "SecureString",
		"Overwrite":   true,
		"Description": "1",
		"KeyId":       aws.GetKMSKeyAlias(),
	}
	_, err = s.ssmRequest("AmazonSSM.PutParameter", putPayload)
	if err != nil {
		return err
	}
	if len(tags) > 0 {
		// AddTags
		var tagList []map[string]string
		for k, v := range tags {
			tagList = append(tagList, map[string]string{"Key": k, "Value": v})
		}
		// Need to convert to proper payload: Tags: [{Key, Value}]
		var tagsArr []interface{}
		for _, t := range tagList {
			tagsArr = append(tagsArr, map[string]interface{}{"Key": t["Key"], "Value": t["Value"]})
		}
		tagPayload := map[string]interface{}{
			"ResourceType": "Parameter",
			"ResourceId":   full,
			"Tags":         tagsArr,
		}
		_, err = s.ssmRequest("AmazonSSM.AddTagsToResource", tagPayload)
		return err
	}
	return nil
}

