	}
	newStr, _ := json.Marshal(existing)
	if !exists {
		// CreateSecret
		createPayload := map[string]interface{}{
			"Name":         service,
			"SecretString": string(newStr),
		}
		_, _, err = aws.JSONRequest("secretsmanager", "secretsmanager.CreateSecret", createPayload, region, creds, s.Retries)
		return err
	}
	putPayload := map[string]interface{}{
		"SecretId":     service,
		"SecretString": string(newStr),
	}
	_, _, err = aws.JSONRequest("secretsmanager", "secretsmanager.PutSecretValue", putPayload, region, creds, s.Retries)
	return err
