func (s *SecretsManagerStore) Delete(service, key string) error {
	creds, region, err := aws.MustCredentials("Secrets Manager", "GetSecretValue", s.Retries)
	if err != nil {
		return err
	}
	payload := map[string]interface{}{"SecretId": service}
	resp, _, err := aws.JSONRequest("secretsmanager", "secretsmanager.GetSecretValue", payload, region, creds, s.Retries)
	if err != nil {
		return fmt.Errorf("secret not found")
	}
	ss, _ := resp["SecretString"].(string)
	var m map[string]interface{}
	json.Unmarshal([]byte(ss), &m)
	if m == nil {
		m = map[string]interface{}{}
	}
	lowerKey := strings.ToLower(key)
	found := false
	for k := range m {
		if k == "_chamber_metadata" {
			continue
		}
		if strings.ToLower(k) == lowerKey {
			delete(m, k)
			found = true
			break
		}
	}
	if !found {
		return fmt.Errorf("secret not found")
	}
	newStr, _ := json.Marshal(m)
	putPayload := map[string]interface{}{
		"SecretId":     service,
		"SecretString": string(newStr),
	}
	// Original delete uses Describe + Put with VersionStages? Our simplified Put without stages may still work with moto? Moto may require VersionStages? Original Put for delete had VersionStages ["AWSCURRENT","CHAMBER1"]? Actually delete log showed Put with VersionStages? Let's include.
