	}
	payload := map[string]interface{}{}
	resp, _, err := aws.JSONRequest("secretsmanager", "secretsmanager.ListSecrets", payload, region, creds, s.Retries)
	if err != nil {
		return nil, fmt.Errorf("Failed to list store contents: %w", err)
	}
	list, _ := resp["SecretList"].([]interface{})
	var out []string
	for _, item := range list {
		m, _ := item.(map[string]interface{})
		name, _ := m["Name"].(string)
		if prefix != "" && !strings.HasPrefix("/"+name, "/"+prefix) && name != prefix {
			// filter? Original list-services with prefix filters? For SM, prefix handling? Simplify: if prefix != "", only include matching
			if !strings.HasPrefix(name, prefix) {
