package cmd

import (
	"fmt"
	"io"
	"os"
	"strings"

	"chamber/util"
	"github.com/spf13/cobra"
)

func init() {
	cmd := &cobra.Command{
		Use:   "write <service> <key> [--] <value|->",
		Short: "write a secret",
		Args:  cobra.ExactArgs(3),
		RunE:  runWrite,
	}
	cmd.Flags().BoolP("singleline", "s", false, "Insert single line parameter (end with \\n)")
	cmd.Flags().Bool("skip-unchanged", false, "Skip writing secret if value is unchanged")
	cmd.Flags().StringToStringP("tags", "t", map[string]string{}, "Add tags to the secret; new secrets only")
	rootCmd.AddCommand(cmd)
}

func runWrite(cmd *cobra.Command, args []string) error {
	cmd.SilenceUsage = true
	serviceRaw := args[0]
	keyRaw := args[1]
	valueRaw := args[2]

	// Validate service and key
	if err := util.ValidateServiceForWrite(serviceRaw); err != nil {
		return err
	}
	// Key validation: key with slash should fail? Our util.ValidateKey will fail for slash.
	if err := util.ValidateKeyForWrite(keyRaw); err != nil {
		return err
	}
	service := util.NormalizeService(serviceRaw)
	key := util.NormalizeKey(keyRaw, false)

	// Handle value from stdin or --?
	value := valueRaw
	if value == "-" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return err
		}
		value = string(data)
	}
	singleline, _ := cmd.Flags().GetBool("singleline")
	if singleline {
		// take first line? Observed: "a\nb\n" with -s gives "a", "hello\n" gives "hello"
		// Likely strings.Split(value, "\n")[0]
		if idx := strings.Index(value, "\n"); idx >= 0 {
			value = value[:idx]
		}
		// Also trim trailing \r? Assume just split.
	}
	skipUnchanged, _ := cmd.Flags().GetBool("skip-unchanged")
	tags, _ := cmd.Flags().GetStringToString("tags")

	backend, err := resolveBackend(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	if skipUnchanged {
		// try to read existing, if same value, skip
		if sec, err := backend.Read(service, key, -1); err == nil {
			if sec.Value == value {
				return nil
			}
		}
	}

	// For tags on existing: backend.Write will return error "tags on write only supported for new secrets"
	if err := backend.Write(service, key, value, tags); err != nil {
		return err
	}
	return nil
}
