	rootCmd.AddCommand(cmd)
}

func runDelete(cmd *cobra.Command, args []string) error {
	cmd.SilenceUsage = true
	serviceRaw := args[0]
	keyRaw := args[1]
	exact, _ := cmd.Flags().GetBool("exact-key")
	service := util.NormalizeService(serviceRaw)
	var key string
	if exact {
		key = keyRaw
	} else {
		key = util.NormalizeKey(keyRaw, false)
	}
	backend, err := resolveBackend(cmd)
	if err != nil {
		return wrapStoreError("Failed to get secret store: %w", err)
	}
	if err := backend.Delete(service, key); err != nil {
		return err
	}
	return nil
}

func wrapStoreError(format string, err error) error {
	// helper to format
	return formatError(format, err)
}
