	secrets, err := backend.ListSecretsByPath(service)
	if err != nil {
		return err
	}
	sort.Slice(secrets, func(i, j int) bool {
		// sort by upper key? Original env output sorted BAR, BAZ, FOO (upper alphabetical). For preserve, sorted bar, baz, foo (lower). So sort by final env name?
		// We'll sort by upper of key.
		ai := secrets[i].Key
		aj := secrets[j].Key
		if !preserve {
			ai = strings.ToUpper(ai)
			aj = strings.ToUpper(aj)
		}
		return ai < aj
	})
	for _, s := range secrets {
		name := s.Key
		if !preserve {
			name = strings.ToUpper(name)
