			escaped = strings.ReplaceAll(escaped, "\t", "\\t")
			fmt.Printf("export %s=\"%s\"\n", name, escaped)
		} else {
			// single quotes: export BAR='value' with single quotes, preserving newline? Observed: export BAR='bar val with spaces\nand newline' with literal newline inside single quotes.
