{"command": "cat > cmd/export_cmd.go <<'GO'
package cmd

import (
	"encoding/csv"
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"

	"chamber/util"
	"github.com/spf13/cobra"
	"gopkg.in/yaml.v3"
)

func init() {
	cmd := &cobra.Command{
		Use:   "export <service...>",
		Short: "Exports parameters in the specified format",
		Args:  cobra.MinimumNArgs(1),
		RunE:  runExport,
	}
	cmd.Flags().StringP("format", "f", "json", "Output format (json, yaml, java-properties, csv, tsv, dotenv, tfvars)")
	cmd.Flags().StringP("output-file", "o", "", "Output file (default is standard output)")
	rootCmd.AddCommand(cmd)
}

func runExport(cmd *cobra.Command, args []string) error {
	cmd.SilenceUsage = true
	format, _ := cmd.Flags().GetString("format")
	outputFile, _ := cmd.Flags().GetString("output-file")
	backend, err := resolveBackend(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}
	// collect secrets from all services, with warnings for duplicates
	merged := map[string]string{}
	// need to track which service each key came from for warning? Original warning: "warning: parameter foo specified more than once (overridden by service myservice)"
	// For duplicate, warning shows key and overriding service (last service wins?).
	// Order: services in args order, later overrides earlier? Our earlier test with export myservice myservice (same service twice) gave warnings for each key (bar, baz, foo) with service myservice (the second occurrence overrides first, but same service, still warns).
	// So for each service in order, for each key, if already in merged, warn to stderr.
	for _, svcRaw := range args {
		svc := util.NormalizeService(svcRaw)
		secrets, err := backend.ListSecretsByPath(svc)
		if err != nil {
			return err
		}
		for _, s := range secrets {
			// keys in merged are lower? Original export json keys are lower (foo, bar). So use lower? Or as stored? Stored lower.
			k := strings.ToLower(s.Key)
			if _, exists := merged[k]; exists {
				fmt.Fprintf(os.Stderr, "warning: parameter %s specified more than once (overridden by service %s)\n", k, svc)
			}
			merged[k] = s.Value
		}
	}
	// sort keys for output? Original outputs sorted.
	var keys []string
	for k := range merged {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var out string
	switch format {
	case "json":
		// compact json with sorted keys, need to ensure order? json.Marshal on map sorts keys, but we can marshal manually to ensure.
		m := map[string]string{}
		for k, v := range merged {
			m[k] = v
		}
		b, _ := json.Marshal(m)
		out = string(b) + "\n"
	case "yaml":
		// Use yaml.v3 to marshal? Original yaml output for our dataset:
		// bar: |-
		//   bar val with spaces
		//   and newline
		// baz: quote"test
		// foo: fooval
		// yaml.v3 should produce similar? Need to test.
		// Use map with sorted keys? yaml.Marshal sorts? Actually yaml.v3 marshals maps sorted? Let's use ordered map via MapSlice? Simpler: use yaml.Marshal on map[string]string (will sort?).
		// To ensure sorted, we can create yaml.Node? Easier: marshal map, it will sort.
		b, _ := yaml.Marshal(merged)
		out = string(b)
	case "dotenv":
		// BAR="value" with upper, sorted, escaped like env -e but without export
		var lines []string
		for _, k := range keys {
			v := merged[k]
			upper := strings.ToUpper(k)
			escaped := strings.ReplaceAll(v, "\\", "\\\\")
			escaped = strings.ReplaceAll(escaped, "\"", "\\\"")
			escaped = strings.ReplaceAll(escaped, "\n", "\\n")
			escaped = strings.ReplaceAll(escaped, "\r", "\\r")
			escaped = strings.ReplaceAll(escaped, "\t", "\\t")
			lines = append(lines, fmt.Sprintf("%s=\"%s\"", upper, escaped))
		}
		if len(lines) > 0 {
			out = strings.Join(lines, "\n") + "\n"
		} else {
			out = ""
		}
	case "csv":
		var buf bytes.Buffer
		w := csv.NewWriter(&buf)
		for _, k := range keys {
			w.Write([]string{k, merged[k]})
		}
		w.Flush()
		out = buf.String()
	case "tsv":
		var buf bytes.Buffer
		w := csv.NewWriter(&buf)
		w.Comma = '\t'
		for _, k := range keys {
			w.Write([]string{k, merged[k]})
		}
		w.Flush()
		out = buf.String()
	case "java-properties":
		var lines []string
		for _, k := range keys {
			v := merged[k]
			// escape newline as \n? Observed: bar = bar val with spaces\nand newline (escaped)
			escaped := strings.ReplaceAll(v, "\\", "\\\\")
			escaped = strings.ReplaceAll(escaped, "\n", "\\n")
			escaped = strings.ReplaceAll(escaped, "\r", "\\r")
			escaped = strings.ReplaceAll(escaped, "\t", "\\t")
			// what about = and : and #? Probably escape? For now, keep simple.
			lines = append(lines, fmt.Sprintf("%s = %s", k, escaped))
		}
		if len(lines) > 0 {
			out = strings.Join(lines, "\n") + "\n"
		}
	case "tfvars":
		var lines []string
		for _, k := range keys {
			v := merged[k]
			// tfvars: bar = "value" with escaping like json string?
			// Observed: bar = "bar val with spaces\nand newline", baz = "quote\"test"
			// Use json-like escaping for string content?
			// Use Go's %q? That would give "bar val with spaces\nand newline" with Go escaping (similar).
			// Let's use json.Marshal for value to get quoted string, then format as `k = quoted`
			b, _ := json.Marshal(v)
			lines = append(lines, fmt.Sprintf("%s = %s", k, string(b)))
		}
		if len(lines) > 0 {
			out = strings.Join(lines, "\n") + "\n"
		}
	default:
		return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", format)
	}

	if outputFile != "" {
		if err := os.WriteFile(outputFile, []byte(out), 0644); err != nil {
			return err
		}
	} else {
