func execCommand(command []string, env []string) error {
	c := exec.Command(command[0], command[1:]...)
	c.Env = env
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	err := c.Run()
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			if ws := exitErr.ProcessState; ws != nil {
				os.Exit(ws.ExitCode())
			}
			return err
		}
		return fmt.Errorf("exec: %q: executable file not found in $PATH", command[0])
	}
	return nil
}
