		var valStr string
		switch vv := v.(type) {
		case string:
			valStr = vv
		case int, int64, float64, bool:
			// Convert to string? Or marshal?
			valStr = fmt.Sprintf("%v", vv)
		case nil:
			valStr = ""
		default:
			// For complex types, marshal to JSON?
			b, _ := json.Marshal(vv)
			// If it's quoted string, unquote?
			var s string
			if err := json.Unmarshal(b, &s); err == nil {
				valStr = s
			} else {
				valStr = string(b)
			}
		}
		if err := backend.Write(service, key, valStr, nil); err != nil {
			return fmt.Errorf("Failed to write secret: %w", err)
		}
		count++
	}
	fmt.Printf("Successfully imported %d secrets\n", count)
	return nil
}
