package cmd

import (
	"fmt"
	"regexp"
	"sort"
	"strings"

	"chamber/util"
	"github.com/spf13/cobra"
)

var unquotedSafeRegex = regexp.MustCompile(`^[A-Za-z0-9_@%+=:,./-]+$`)

func isUnquotedSafe(s string) bool {
	if s == "" {
		return false
	}
	return unquotedSafeRegex.MatchString(s)
}

func escapeDoubleQuoted(s string) string {
	// escape \, ", $, `, newline, etc. as observed
	// Order: escape \ first
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	s = strings.ReplaceAll(s, "$", "\\$")
	s = strings.ReplaceAll(s, "`", "\\`")
	s = strings.ReplaceAll(s, "\n", "\\n")
	s = strings.ReplaceAll(s, "\r", "\\r")
	s = strings.ReplaceAll(s, "\t", "\\t")
	// What about ! ? Original does not escape !, *, #, etc.
	return s
}

func init() {
	cmd := &cobra.Command{
		Use:   "env <service>",
		Short: "Print the secrets from the parameter store in a format to export as environment variables",
		Args:  cobra.ExactArgs(1),
		RunE:  runEnv,
	}
	cmd.Flags().BoolP("preserve-case", "p", false, "preserve variable name case")
	cmd.Flags().BoolP("escape-strings", "e", false, "escape special characters in values")
	cmd.Flags().SortFlags = false
	rootCmd.AddCommand(cmd)
}

func runEnv(cmd *cobra.Command, args []string) error {
	cmd.SilenceUsage = true
	service := util.NormalizeService(args[0])
	backend, err := resolveBackend(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}
	preserve, _ := cmd.Flags().GetBool("preserve-case")
	escape, _ := cmd.Flags().GetBool("escape-strings")
	secrets, err := backend.ListSecretsByPath(service)
	if err != nil {
		return err
	}
	sort.Slice(secrets, func(i, j int) bool {
		ai := secrets[i].Key
		aj := secrets[j].Key
		if !preserve {
			ai = strings.ToUpper(ai)
			aj = strings.ToUpper(aj)
		}
		return ai < aj
	})
	for _, s := range secrets {
		name := s.Key
		if !preserve {
			name = strings.ToUpper(name)
		}
		val := s.Value
		if escape {
			escaped := escapeDoubleQuoted(val)
			fmt.Printf("export %s=\"%s\"\n", name, escaped)
		} else {
			if isUnquotedSafe(val) {
				fmt.Printf("export %s=%s\n", name, val)
			} else if val == "" {
				fmt.Printf("export %s=''\n", name)
			} else {
				escaped := strings.ReplaceAll(val, "'", "'\"'\"'")
				fmt.Printf("export %s='%s'\n", name, escaped)
			}
		}
	}
	return nil
}
