package store

import (
	"chamber/aws"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"time"
)

type S3Store struct {
	Bucket      string
	Retries     int
	KMSKeyAlias string
	UseKMS      bool
}

func (s *S3Store) s3Get(key string) ([]byte, int, error) {
	creds, region, err := aws.MustCredentials("S3", "GetObject", s.Retries)
	if err != nil {
		return nil, 0, err
	}
	// region required for S3
	if region == "" {
		region, _ = aws.GetRegionRequired()
		if region == "" {
			return nil, 0, fmt.Errorf("Failed to list store contents: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
		}
	}
	// Check region env for S3? GetRegionRequired already checks
	if osRegion := getEnvRegion(); osRegion == "" {
		return nil, 0, fmt.Errorf("Failed to list store contents: operation error S3: GetObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
	}
	body, status, err := aws.S3Request("GET", s.Bucket, key, nil, region, creds, "")
	if err != nil {
		return nil, status, err
	}
	return body, status, nil
}

func getEnvRegion() string {
	// check AWS_REGION
	if v := getEnv("AWS_REGION"); v != "" {
		return v
	}
	if v := getEnv("AWS_DEFAULT_REGION"); v != "" {
		return v
	}
	return ""
}

func getEnv(k string) string {
	// use os.Getenv via aws? To avoid import cycle, just use os
	return aws.GetEnv(k)
}

func (s *S3Store) s3Put(key string, data []byte) error {
	creds, region, err := aws.MustCredentials("S3", "PutObject", s.Retries)
	if err != nil {
		return err
	}
	if getEnvRegion() == "" {
		return fmt.Errorf("Failed to list store contents: operation error S3: PutObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
	}
	_, _, err = aws.S3Request("PUT", s.Bucket, key, data, region, creds, "application/json")
	return err
}

func (s *S3Store) s3Delete(key string) error {
	creds, region, err := aws.MustCredentials("S3", "DeleteObject", s.Retries)
	if err != nil {
		return err
	}
	if getEnvRegion() == "" {
		return fmt.Errorf("Failed to list store contents: operation error S3: DeleteObject, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
	}
	_, _, err = aws.S3Request("DELETE", s.Bucket, key, nil, region, creds, "")
	return err
}

func (s *S3Store) s3List(prefix string) ([]string, error) {
	creds, region, err := aws.MustCredentials("S3", "ListObjectsV2", s.Retries)
	if err != nil {
		return nil, err
	}
	if getEnvRegion() == "" {
		return nil, fmt.Errorf("Failed to list store contents: operation error S3: ListObjectsV2, resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
	}
	keys, err := aws.S3List(s.Bucket, prefix, region, creds)
	if err != nil {
		return nil, err
	}
	return keys, nil
}

// S3 JSON format: per-key file service/key.json contains {"Value": "...", "Version": 1, "User": "...", "LastModified": ...}
// For simplicity, store as {"value": "..."}? Let's use {"Value": "..."} to be compatible with our own reads.
// For list, we need to discover keys via ListObjects.

func (s *S3Store) List(service string, includeValues bool) ([]Secret, error) {
	keys, err := s.s3List(service + "/")
	if err != nil {
		return nil, err
	}
	var out []Secret
	for _, k := range keys {
		// k is like service/key.json or service/__latest.json etc. Skip __latest and __kms
		if strings.Contains(k, "__latest") || strings.Contains(k, "__kms") {
			continue
		}
		// extract key: remove prefix service/ and suffix .json
		rel := strings.TrimPrefix(k, service+"/")
		if strings.Contains(rel, "/") {
			// nested? For service with slash, e.g., service my/service, keys are my/service/key.json -> rel key.json, ok. For deeper, ignore?
			// If rel contains '/', it means sub-service? For OneLevel, only direct children. So skip if contains '/'?
			continue
		}
		keyName := strings.TrimSuffix(rel, ".json")
		if keyName == "" {
			continue
		}
		sec := Secret{Key: keyName, Version: 0, LastModified: time.Time{}, User: ""}
		if includeValues {
			body, status, err := s.s3Get(k)
			if err != nil || status != 200 {
				continue
			}
			var m map[string]interface{}
			json.Unmarshal(body, &m)
			if v, ok := m["Value"].(string); ok {
				sec.Value = v
			} else if v, ok := m["value"].(string); ok {
				sec.Value = v
			} else {
				// try raw string? If file contains plain JSON string?
				sec.Value = string(body)
			}
		}
		out = append(out, sec)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Key < out[j].Key })
	return out, nil
}

func (s *S3Store) ListSecretsByPath(service string) ([]Secret, error) {
	// same as List with values
	secrets, err := s.List(service, true)
	if err != nil {
		return nil, err
	}
	return secrets, nil
}

func (s *S3Store) Read(service, key string, version int) (*Secret, error) {
	s3key := service + "/" + key + ".json"
	body, status, err := s.s3Get(s3key)
	if err != nil || status != 200 {
		return nil, fmt.Errorf("Failed to read: secret not found")
	}
	var m map[string]interface{}
	json.Unmarshal(body, &m)
	var val string
	if v, ok := m["Value"].(string); ok {
		val = v
	} else if v, ok := m["value"].(string); ok {
		val = v
	} else {
		val = string(body)
	}
	// Version? Try to get from map?
	ver := 0
	if v, ok := m["Version"]; ok {
		switch vv := v.(type) {
		case float64:
			ver = int(vv)
		case int:
			ver = vv
		}
	}
	return &Secret{Key: key, Value: val, Version: ver, LastModified: time.Time{}, User: ""}, nil
}

func (s *S3Store) Write(service, key, value string, tags map[string]string) error {
	s3key := service + "/" + key + ".json"
	m := map[string]interface{}{"Value": value, "Version": 1}
	data, _ := json.Marshal(m)
	return s.s3Put(s3key, data)
}

func (s *S3Store) Delete(service, key string) error {
	s3key := service + "/" + key + ".json"
	// Check exists?
	_, status, err := s.s3Get(s3key)
	if err != nil || status != 200 {
		return fmt.Errorf("secret not found")
	}
	return s.s3Delete(s3key)
}

func (s *S3Store) History(service, key string) ([]SecretVersion, error) {
	return []SecretVersion{}, nil
}

func (s *S3Store) ListServices(prefix string, includeSecrets bool) ([]string, error) {
	// List all objects, extract services
	var listPrefix string
	if prefix != "" {
		listPrefix = prefix
	} else {
		listPrefix = ""
	}
	keys, err := s.s3List(listPrefix)
	if err != nil {
		return nil, err
	}
	if includeSecrets {
		var out []string
		for _, k := range keys {
			if strings.Contains(k, "__latest") || strings.Contains(k, "__kms") {
				continue
			}
			// k is like service/key.json, need to return /service/key? Original list-services -s returns /svc1/key1 with leading slash, no .json?
			// Our S3 keys are service/key.json, so strip .json and add leading slash?
			trim := strings.TrimSuffix(k, ".json")
			out = append(out, "/"+trim)
		}
		sort.Strings(out)
		return out, nil
	}
	seen := map[string]bool{}
	var out []string
	for _, k := range keys {
		if strings.Contains(k, "__latest") || strings.Contains(k, "__kms") {
			continue
		}
		// service is first part before /
		parts := strings.Split(k, "/")
		if len(parts) == 0 {
			continue
		}
		svc := parts[0]
		// For prefix filtering? If prefix != "", only include matching? Our s3List already filtered by prefix, so all match.
		if !seen[svc] {
			seen[svc] = true
			out = append(out, svc)
		}
	}
	sort.Strings(out)
	return out, nil
}

func (s *S3Store) ReadTags(service, key string) (map[string]string, error) {
	return map[string]string{}, nil
}
func (s *S3Store) WriteTags(service, key string, tags map[string]string, deleteOther bool) (map[string]string, error) {
	return tags, nil
}
func (s *S3Store) DeleteTags(service, key string, tagKeys []string) error {
	return nil
