func S3List(bucket, prefix, region string, creds *Credentials) ([]string, error) {
	endpoint := GetEndpoint("s3", region)
	// Build URL: endpoint/bucket?list-type=2&prefix=prefix
	u, _ := url.Parse(endpoint + "/" + bucket)
	q := u.Query()
	q.Set("list-type", "2")
	if prefix != "" {
		q.Set("prefix", prefix)
	}
	u.RawQuery = q.Encode()
	req, _ := http.NewRequest("GET", u.String(), nil)
	// Sign? For List, need signing with s3 service, empty payload?
	emptyHash := sha256.Sum256([]byte{})
	payloadHash := hex.EncodeToString(emptyHash[:])
	req.Header.Set("X-Amz-Content-Sha256", payloadHash)
	if creds.SessionToken != "" {
		req.Header.Set("X-Amz-Security-Token", creds.SessionToken)
	}
	signRequest(req, []byte{}, "s3", region, creds, "")
	client := &http.Client{Timeout: 30 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("s3 list error %d: %s", resp.StatusCode, string(b))
	}
	// Parse XML for <Key>
	s := string(b)
	var keys []string
	// Simple parsing: find <Key>...</Key>
	for {
		start := strings.Index(s, "<Key>")
		if start < 0 {
			break
		}
		end := strings.Index(s[start:], "</Key>")
		if end < 0 {
			break
		}
		key := s[start+5 : start+end]
		keys = append(keys, key)
		s = s[start+end+6:]
	}
	return keys, nil
}
